def cka(X,Y):
    X=X-X.mean(0); Y=Y-Y.mean(0)
    return np.linalg.norm(X.T@Y)**2/(np.linalg.norm(X.T@X)*np.linalg.norm(Y.T@Y))
def rel(X,Y):
    return np.linalg.norm(Y-X)/np.linalg.norm(X)
